// Question bank + grading for the Korean "Symbols" quiz.
//
// One QuizItem is one (letter, position) concept - e.g. "ㅅ at the end of a syllable" is a different
// item from "ㅅ at the start", because it sounds different (t vs s). Each item has several variants
// (different English words) so repeated quizzes don't feel identical. Progress is tracked per item.
//
// Accuracy bar is the same as src/lib/hangul.ts: nothing here is generated by an LLM at runtime, and
// the sound claims follow the same deliberate calls (plain / aspirated / tense stops via go / kite /
// sky, ㅓ = "u in cup", ㅅ -> "sh" before ㅣ, finals neutralize to seven sounds, ㅐ/ㅔ told apart by
// their Revised Romanization code even though modern speech merges them).

import { HANGUL_SYMBOLS } from "./hangul";
import { blankedWord, fullWord } from "./hangulBlocks";
import { explainWrong } from "./hangulMisconceptions";
import type { Grade, QuizDefinition, QuizItem as BaseItem, QuizVariant as BaseVariant } from "./quizTypes";
export { blankedWord, decomposeBlock, fullWord } from "./hangulBlocks";
export type { Grade } from "./quizTypes";

export type QuizPosition = "initial" | "medial" | "final" | "vowel";

export const POSITION_LABEL: Record<QuizPosition, string> = {
  initial: "Start of a syllable",
  medial: "Between vowels",
  final: "End of a syllable",
  vowel: "Vowel",
};

export type QuizVariant = BaseVariant & {
  // Letters that share a sound (the finals ㄷㅅㅈㅊㅌㅆㅎ all end in t; ㅙ ㅚ ㅞ all say "weh") need a
  // Korean word to pin down which one is meant: `before + block + after`, with one letter of the
  // block blanked (its final by default, or its vowel).
  ko?: { before?: string; block: string; after?: string; blank?: "final" | "vowel"; gloss: string };
};

// id: "i:ㄱ" initial, "m:ㄱ" medial, "f:ㄱ" final, "v:ㅏ" vowel. `answer` is the one canonical jamo
// and `code` the Revised Romanization shown with the question.
export type QuizItem = Omit<BaseItem, "variants"> & {
  position: QuizPosition;
  variants: QuizVariant[];
};

// --- Authoring helpers -------------------------------------------------------------------------

type V = [text: string, extra?: Omit<QuizVariant, "text" | "context">];

const variants = (list: V[]): QuizVariant[] => list.map(([text, extra]) => ({ text, ...extra }));

const initial = (answer: string, code: string, note: string, list: V[]): QuizItem => ({
  id: `i:${answer}`,
  answer,
  position: "initial",
  group: POSITION_LABEL["initial"],
  code,
  note,
  variants: variants(list),
});

const medial = (answer: string, code: string, note: string, list: V[]): QuizItem => ({
  id: `m:${answer}`,
  answer,
  position: "medial",
  group: POSITION_LABEL["medial"],
  code,
  note,
  variants: variants(list),
});

const final = (answer: string, code: string, note: string, list: V[]): QuizItem => ({
  id: `f:${answer}`,
  answer,
  position: "final",
  group: POSITION_LABEL["final"],
  code,
  note,
  variants: variants(list),
});

const vowel = (answer: string, code: string, note: string, list: V[]): QuizItem => ({
  id: `v:${answer}`,
  answer,
  position: "vowel",
  group: POSITION_LABEL["vowel"],
  code,
  note,
  variants: variants(list),
});

// Korean-word context for a final-position variant.
const ko = (block: string, gloss: string, before = "", after = ""): { ko: NonNullable<QuizVariant["ko"]> } => ({
  ko: { before, block, after, gloss },
});

// Same, but the block's vowel is the blank.
const vko = (block: string, gloss: string, before = "", after = ""): { ko: NonNullable<QuizVariant["ko"]> } => ({
  ko: { before, block, after, blank: "vowel", gloss },
});

