export const QUIZ_ITEMS: QuizItem[] = [...INITIALS, ...MEDIALS, ...FINALS, ...VOWEL_ITEMS];

const ITEM_BY_ID = new Map(QUIZ_ITEMS.map((item) => [item.id, item]));

export function itemById(id: string): QuizItem | undefined {
  return ITEM_BY_ID.get(id);
}

export const DEFAULT_PROMPT = "Write the Hangul letter for the bold sound.";

export function variantCode(item: QuizItem, variantIndex: number): string {
  return item.variants[variantIndex]?.code ?? item.code;
}

// --- Grading -----------------------------------------------------------------------------------

// Compatibility jamo (what phone keyboards and IMEs produce) keyed by the conjoining jamo that
// NFKD turns them into, so input in either block compares equal.
const COMPAT_JAMO = new Set(HANGUL_SYMBOLS.map((s) => s.jamo));
const CONJOINING_TO_COMPAT = new Map<string, string>(
  [...COMPAT_JAMO].map((jamo) => [jamo.normalize("NFKD"), jamo]),
);

const VOWEL_JAMO = new Set(
  HANGUL_SYMBOLS.filter((s) => s.kind === "Vowel" || s.kind === "Compound vowel").map((s) => s.jamo),
);

// Keystroke pairs that make one letter.
const FUSED_LETTERS = new Map<string, string>([
  ["ㅗㅏ", "ㅘ"], ["ㅗㅐ", "ㅙ"], ["ㅗㅣ", "ㅚ"], ["ㅜㅓ", "ㅝ"], ["ㅜㅔ", "ㅞ"], ["ㅜㅣ", "ㅟ"], ["ㅡㅣ", "ㅢ"],
  ["ㄱㄱ", "ㄲ"], ["ㄷㄷ", "ㄸ"], ["ㅂㅂ", "ㅃ"], ["ㅅㅅ", "ㅆ"], ["ㅈㅈ", "ㅉ"],
]);

function normalizeGiven(input: string): { jamo: string } | { error: string } {
  const text = input.trim();
  if (!text) return { error: "Type the Hangul letter first - or tap one on the keypad." };
  const chars = [...text];
  if (chars.length > 1) {
    // Some keyboards/IMEs don't fuse a lone vowel pair or a doubled consonant into one letter, so
    // accept the keystrokes that make up a compound letter: ㅗ ㅏ -> ㅘ, ㅅ ㅅ -> ㅆ.
    const fused = chars.length === 2 ? FUSED_LETTERS.get(chars.join("")) : undefined;
    if (fused) return { jamo: fused };
    if (chars.length === 2 && chars.every((c) => VOWEL_JAMO.has(c))) {
      return {
        error: `${chars.join(" + ")} doesn't combine into a Hangul vowel. The "wa" sound is ㅘ (ㅗ + ㅏ), "wuh" is ㅝ (ㅜ + ㅓ), "weh" is ㅞ (ㅜ + ㅔ). The keypad has every vowel as one key.`,
      };
    }
    return { error: "Type just one letter - not a whole syllable or word." };
  }
  const ch = chars[0];
  const code = ch.codePointAt(0) ?? 0;
  if (code >= 0xac00 && code <= 0xd7a3) {
    return { error: `${ch} is a whole syllable block. This quiz asks for a single letter - one consonant or one vowel.` };
  }
  const compat = COMPAT_JAMO.has(ch) ? ch : (CONJOINING_TO_COMPAT.get(ch) ?? CONJOINING_TO_COMPAT.get(ch.normalize("NFKD")));
  if (compat) return { jamo: compat };
  if (/^[a-z]$/i.test(ch)) {
    return { error: "That's a Latin letter. Switch to a Korean keyboard, or tap a letter on the keypad below." };
  }
  return { error: "That isn't one of the 40 Hangul letters. Try the keypad below." };
}

export function gradeAnswer(item: QuizItem, variantIndex: number, input: string): Grade {
  const normalized = normalizeGiven(input);
  if ("error" in normalized) return { status: "invalid", message: normalized.error };
  if (normalized.jamo === item.answer) return { status: "correct" };
  const variant = item.variants[variantIndex] ?? item.variants[0];
  return { status: "wrong", given: normalized.jamo, message: explainWrong(item, variant, normalized.jamo) };
}

// Resolve each Korean-word context into the generic shape the quiz UI reads.
for (const item of QUIZ_ITEMS) {
  for (const v of item.variants) {
    if (!v.ko) continue;
    const blank = blankedWord(v.ko);
    if (blank) v.context = { blank, full: fullWord(v.ko), gloss: v.ko.gloss };
  }
}

const SYMBOL_NAME = new Map(HANGUL_SYMBOLS.map((s) => [s.jamo, s.name]));

const AUDIO_SYLLABLE = new Map(HANGUL_SYMBOLS.map((s) => [s.jamo, s.audioSyllable]));

export const HANGUL_QUIZ: QuizDefinition = {
  deck: "symbols",
  languageCode: "ko",
  statsKey: "symbols",
  answerSize: "letter",
  // A lone jamo is read by its name, so play the representative syllable (ㄱ -> 가), as the flashcards do.
  audioSrc: (item) => {
    const text = AUDIO_SYLLABLE.get(item.answer);
    return text ? `/api/tts?lang=ko&text=${encodeURIComponent(text)}` : null;
  },
  title: "Symbols quiz",
  intro:
    "You'll see an English word with the sound in bold, plus its phonetic code. Write the Hangul letter for that sound - the same letter can sound different at the start and the end of a syllable, so each position gets its own question.",
  defaultPrompt: DEFAULT_PROMPT,
  placeholder: "ㅎ",
  inputLang: "ko",
  contextLabel: "In the Korean word",
  items: QUIZ_ITEMS,
  groups: [POSITION_LABEL.initial, POSITION_LABEL.medial, POSITION_LABEL.final, POSITION_LABEL.vowel],
  itemById,
  variantCode,
  grade: (item, variantIndex, input) => gradeAnswer(item as QuizItem, variantIndex, input),
  answerLabel: (item) => SYMBOL_NAME.get(item.answer) ?? null,
};
